## Flutter BLoC/Cubit Integration Guide

### How to Integrate User Authentication Data with Your Existing Dashboard BLoC/Cubit

---

## Option 1: Cubit-Based Integration (Recommended)

### Step 1: Add to Your DashboardCubit

```dart
// lib/features/dashboard/presentation/cubit/dashboard_cubit.dart

class DashboardCubit extends Cubit<DashboardState> {
  DashboardCubit() : super(const DashboardState.initial());

  // Add this method to handle authentication data
  Future<void> initializeDashboard({
    required String email,
    required String userId,
    required String token,
  }) async {
    emit(const DashboardState.loading());
    try {
      // Store token if needed for API calls
      _storageService.saveToken(token);

      // Fetch dashboard data if needed
      final dashboardData = await _dashboardRepository.fetchDashboard(
        userId: userId,
        token: token,
      );

      emit(DashboardState.loaded(
        dashboardData: dashboardData,
        userEmail: email,
        userId: userId,
      ));
    } catch (e) {
      emit(DashboardState.error(message: e.toString()));
    }
  }
}
```

### Step 2: Update Your DashboardState

```dart
// lib/features/dashboard/presentation/cubit/dashboard_state.dart

@freezed
class DashboardState with _$DashboardState {
  const factory DashboardState.initial() = _Initial;
  const factory DashboardState.loading() = _Loading;
  const factory DashboardState.loaded({
    required DashboardData dashboardData,
    required String userEmail,
    required String userId,
  }) = _Loaded;
  const factory DashboardState.error({required String message}) = _Error;
}
```

### Step 3: Update dashboard_page.dart

```dart
// Replace the TODO section with actual Cubit call

Future<void> _getUserSessionFromAndroid() async {
  try {
    final result = await platform.invokeMethod<Map>('getUserSession');

    if (result != null) {
      userEmail = result['email'] as String?;
      userId = result['userId'] as String?;
      token = result['token'] as String?;

      // Call your DashboardCubit initialization
      if (mounted) {
        context.read<DashboardCubit>().initializeDashboard(
          email: userEmail!,
          userId: userId!,
          token: token!,
        );
      }
    }
  } on PlatformException catch (e) {
    setState(() {
      errorMessage = "Failed to get user session: ${e.message}";
      isLoading = false;
    });
  }
}
```

### Step 4: Update your Dashboard UI to Use Cubit State

```dart
@override
Widget build(BuildContext context) {
  return BlocBuilder<DashboardCubit, DashboardState>(
    builder: (context, state) {
      return state.when(
        initial: () => const Scaffold(
          body: Center(child: Text('Initializing...')),
        ),
        loading: () => const Scaffold(
          body: Center(child: CircularProgressIndicator()),
        ),
        loaded: (dashboardData, userEmail, userId) => Scaffold(
          appBar: AppBar(
            title: const Text('Dashboard'),
          ),
          body: SingleChildScrollView(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Welcome, $userEmail!',
                  style: Theme.of(context).textTheme.headlineSmall,
                ),
                const SizedBox(height: 24),
                // Your dashboard content here
                _buildDashboardContent(dashboardData),
              ],
            ),
          ),
        ),
        error: (message) => Scaffold(
          body: Center(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Text('Error: $message'),
                const SizedBox(height: 16),
                ElevatedButton(
                  onPressed: _getUserSessionFromAndroid,
                  child: const Text('Retry'),
                ),
              ],
            ),
          ),
        ),
      );
    },
  );
}

Widget _buildDashboardContent(DashboardData data) {
  // Build your dashboard UI using the data
  return Column(
    children: [
      // Your dashboard widgets
    ],
  );
}
```

