## Testing

### Unit Test Example

```dart
void main() {
  group('DashboardCubit', () {
    late DashboardCubit dashboardCubit;
    late MockApiService mockApiService;
    late MockAuthTokenService mockAuthTokenService;

    setUp(() {
      mockApiService = MockApiService();
      mockAuthTokenService = MockAuthTokenService();

      dashboardCubit = DashboardCubit(
        apiService: mockApiService,
        authTokenService: mockAuthTokenService,
      );
    });

    test('emits [Loading, Loaded] when initializeDashboard succeeds', () async {
      // Arrange
      when(mockApiService.getWithAuth<DashboardData>(
        any,
        fromJson: anyNamed('fromJson'),
        token: anyNamed('token'),
      )).thenAnswer((_) async => mockDashboardData);

      // Act
      await dashboardCubit.initializeDashboard(
        email: 'test@example.com',
        userId: 'user123',
        token: 'token123',
      );

      // Assert
      expect(dashboardCubit.state, isA<DashboardStateLoaded>());
    });
  });
}
```

---

## Summary

Choose the integration option that best fits your architecture:
- **Option 1 (Cubit)**: Simple, modern, recommended for new projects
- **Option 2 (BLoC)**: More control, better for complex state management
- **Option 3 (Provider/Riverpod)**: Lightweight, functional approach

All options support proper error handling, token management, and maintainability.

# Quick Code Reference - Exact Changes

## 1. ChannelManager.kt - Complete File

```kotlin
package com.example.androidapp

import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel

object ChannelManager {
    private const val CHANNEL = "com.example.flutter/channel"
    private const val DASHBOARD_CHANNEL = "com.example.flutter/dashboard"

    private var userSession: MutableMap<String, String>? = null

    fun setup(flutterEngine: FlutterEngine) {
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, CHANNEL).setMethodCallHandler { call, result ->
            when (call.method) {
                "getDataFromAndroid" -> {
                    val data = "Hello from Android!"
                    result.success(data)
                }
                else -> result.notImplemented()
            }
        }

        // Setup dashboard channel for authentication data
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, DASHBOARD_CHANNEL).setMethodCallHandler { call, result ->
            when (call.method) {
                "getUserSession" -> {
                    val session = getUserSession()
                    if (session != null) {
                        result.success(session)
                    } else {
                        result.error("NO_SESSION", "User session not found", null)
                    }
                }
                else -> result.notImplemented()
            }
        }
    }

    fun setUserSession(email: String, userId: String, token: String) {
        userSession = mutableMapOf(
            "email" to email,
            "userId" to userId,
            "token" to token
        )
    }

    fun getUserSession(): Map<String, String>? {
        return userSession
    }

    fun clearUserSession() {
        userSession = null
    }
}
```

